def word_frequency(sentence):
    words = sentence.split()
    freq = {} 
    for word in words:
        if word in freq:
            freq[word] += 1
        else:
            freq[word] = 1
    return freq

class Stack:
    def __init__(self):
        self.stack = []
    def push(self, item):
        self.stack.append(item)
    def pop(self):
        if not self.is_empty():
            return self.stack.pop()
        else:
            raise IndexError('Stack is empty')
    def peek(self):
        if not self.is_empty():
            return self.stack[-1]
        else:
            raise IndexError('Stack is empty')
    def is_empty(self):
        return len(self.stack) == 0

def first_non_repeating(s):
    count = {} 
    for c in s:
        if c in count:
            count[c] += 1
        else:
            count[c] = 1
    for c in count:
        if count[c] == 1:
            return c

