class Set: 
    def __init__(self): 
        self.data = {} 

    def add(self, item): 
        if item not in self.data: 
            self.data[item] = 1

    def remove(self, item): 
        if item in self.data: 
            del self.data[item]

    def contains(self, item): 
        return item in self.data

    def union(self, other): 
        result = Set() 
        for item in self.data: 
            result.add(item)
        for item in other.data: 
            result.add(item)
        return result

    def intersection(self, other): 
        result = Set() 
        for item in self.data: 
            if item in other.data: 
                result.add(item)
        return result

    def difference(self, other): 
        result = Set() 
        for item in self.data: 
            if item not in other.data: 
                result.add(item)
        return result

# Test the functions
