from collections import defaultdict

input_nodes = list(map(str, input().split()))
edges = [tuple(map(str, edge)) for edge in list(map(lambda x: x.split(','), input().split()))]
start_node = input()
end_node = input()

graph = defaultdict(list)
for edge in edges:
    graph[edge[0]].append(edge[1])
    graph[edge[1]].append(edge[0])

def dijkstra(graph, start_node, end_node):
    distances = {node: float('inf') for node in graph}
    distances[start_node] = 0
    visited = set()
    while len(visited) < len(graph):
        current_node = min(graph, key=lambda node: distances.get(node, float('inf')))
        if current_node not in visited:
            visited.add(current_node)
            for neighbor in graph[current_node]:
                if neighbor not in visited:
                    new_distance = distances[current_node] + 1
                    if new_distance < distances.get(neighbor, float('inf')):
                        distances[neighbor] = new_distance
    return distances[end_node]

print(dijkstra(graph, start_node, end_node))```

