def build_heap(arr):
    n = len(arr)
    for i in range(n // 2 - 1, -1, -1):
        heapify(arr, n, i)

def heapify(arr, n, i):
    left = 2 * i + 1
    right = 2 * i + 2
    smallest = i
    if left < n and arr[left] < arr[smallest]:
        smallest = left
    if right < n and arr[right] < arr[smallest]:
        smallest = right
    if smallest != i:
        arr[i], arr[smallest] = arr[smallest], arr[i]
        heapify(arr, n, smallest)

def extract_min(arr):
    if len(arr) == 0:
        return None
    temp = arr[0]
    arr[0] = arr[len(arr) - 1]
    arr.pop()
    heapify(arr, len(arr) - 1, 0)
    return temp

