import heapq

def kth_smallest(arr, k):
    heap = arr[:k]
    heapq.heapify(heap)
    for num in arr[k:]:
        if len(heap) > k:
            if num < heap[0]:
                heapq.heappop(heap)
                heapq.heappush(heap, num)
    return heap[0]

