    second_max = float('-inf') # initialize second_max to a small negative number
    for num in nums:
        if num > max_num:
            second_max = max_num
            max_num = num
        elif num > second_max and num != max_num:
            second_max = num
    if second_max == float('-inf'):
        print('There is no second largest number')
    else:
        print(second_max)

