class Set:
    def __init__(self):
        self.set = {
        }
    def add(self, element):
        if element not in self.set:
            self.set[element] = True
    def remove(self, element):
        if element in self.set:
            del self.set[element]
    def __contains__(self, element):
        return element in self.set

