class Node: 
    def __init__(self, data): 
        self.data = data
        self.left = None
        self.right = None

class Tree: 
    def __init__(self, arr, index): 
        self.root = self.build_tree(arr, index)

    def build_tree(self, arr, index): 
        if index < len(arr): 
            node = Node(arr[index])
            index += 1
            node.left = self.build_tree(arr, index)
            index += 1
            node.right = self.build_tree(arr, index)
        else:
            node = None
        return node

    def max_path_sum(self, node): 
        if not node: 
            return 0

        left_sum = self.max_path_sum(node.left)
        right_sum = self.max_path_sum(node.right)

        node_sum = node.data + min(left_sum, right_sum)

        return max(node_sum, max(left_sum, right_sum))

def __starting_point(): 
    arr = [1, 2, 3, 4, None, 5, 6, None, None, 7, None, None, None, 8]
    t = Tree(arr, 0)
    print(t.max_path_sum(t.root))
__starting_point()
