def max_sum_odd_subarray(arr):
    n = len(arr)
    max_sum = -float('inf')
    for i in range(n):
        current_sum = 0
        for j in range(i, n):
            current_sum += arr[j]
            if current_sum % 2 == 1 and current_sum > max_sum:
                max_sum = current_sum
    return max_sum

