import heapq

class Graph:
    def __init__(self):
        self.nodes = {} 
    def add_edge(self, src, dest, weight):
        if src not in self.nodes:
            self.nodes[src] = []
        self.nodes[src].append((dest, weight))
    def shortest_path(self, src, dest):
        q = [(0, src)]
        visited = set()
        while q:
            _, current = heapq.heappop(q)
            if current == dest:
                return current
            if current not in visited:
                visited.add(current)
                for neighbor, weight in self.nodes[current]:
                    if neighbor not in visited:
                        heapq.heappush(q, (weight + current, neighbor))
        return -1

graph = Graph()
for edge in input().splitlines():
    src, dest, weight = edge.split()
    graph.add_edge(src, dest, int(weight))

start, end = input().split()
print(graph.shortest_path(start, end))```

